#!/usr/bin/env python3
import base64, gzip, hashlib
from pathlib import Path

EXPECTED_SOURCE_BYTES=35457
EXPECTED_SOURCE_SHA256='033cd374bcfa0b2091b1de2b6aa442453134f08516f63160848b62814247525a'
EXPECTED_GZIP_BYTES=9890
EXPECTED_GZIP_SHA256='4bebe2db818685ec186dd91538ef1296089b5759eb85d49792c143e7918eab57'
ENCODED=''
gz=base64.b64decode(ENCODED,validate=True)
if len(gz)!=EXPECTED_GZIP_BYTES or hashlib.sha256(gz).hexdigest()!=EXPECTED_GZIP_SHA256:
    raise SystemExit('LU2G candidate gzip identity mismatch')
src=gzip.decompress(gz)
if len(src)!=EXPECTED_SOURCE_BYTES or hashlib.sha256(src).hexdigest()!=EXPECTED_SOURCE_SHA256:
    raise SystemExit('LU2G candidate source identity mismatch')
exec(compile(src,str(Path(__file__)),'exec'),globals(),globals())
